head.script:
scwin.ibx_openPopup_onclick = function(e) {
	if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
	var opts = {
		"id": "Popup1",
		"type": "wframePopup",
		"width": "1024px",
		"height": "600px",
		"top": 250,
		"left": 250,
		"popupName": "Popup Test",
		"modal": false,
		"useIFrame": true,
		"title": "타이틀",
		"frameMode": "iframe",
		"disableCloseButton": false,
		"useControl": true,
		"controls": {
			"minimize": true,
			"maximize": true,
			"close": true
		}
	};
	$p.openPopup("/sample/common_link/p_popup_wframe_slider_width_WESD-282_(WSQ-4448)_sub.xml", opts);
};
